style.css:
@-moz-document domain("web.whatsapp.com") {
/* message text */
  #main .selectable-text, 
  #main .copyable-text,
  /* message images / media */
  #main img, 
  #main video {
    filter: blur(6px) !important;
  }

  /* agar sender/metadata bhi blur karna ho */
  #main .message-out, 
  #main .message-in {
    filter: blur(6px) !important;
  }
}
